import itertools

def is_costas(p):
    n = len(p)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diff = (p[j] - p[i], j - i)
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

def solve():
    # x[2] = 3
    # x is a permutation of {0, 1, 2, 3, 4}
    # x[0], x[1], x[3], x[4] are a permutation of {0, 1, 2, 4}

    for p in itertools.permutations([0, 1, 2, 4]):
        x = [0] * 5
        x[0] = p[0]
        x[1] = p[1]
        x[2] = 3
        x[3] = p[2]
        x[4] = p[3]

        if is_costas(x):
            return x
    return None

print(solve())
